import io
import os
import sys
from rich.console import Console
from rich.file_proxy import FileProxy

def test_isatty_proxy():
    console = Console()
    # Use sys.stdout as the wrapped file
    proxy = FileProxy(console, sys.stdout)

    print(f"Original isatty: {hasattr(sys.stdout, 'isatty')}")
    if hasattr(sys.stdout, 'isatty'):
        print(f"Original isatty value: {sys.stdout.isatty()}")

    print(f"Proxy has isatty: {hasattr(proxy, 'isatty')}")
    if hasattr(proxy, 'isatty'):
        print(f"Proxy isatty value: {proxy.isatty()}")

    # Test with a file that doesn't have isatty but has fileno
    class MockFile:
        def fileno(self):
            return 1
        def write(self, s):
            pass
        def flush(self):
            pass

    mock_file = MockFile()
    proxy_mock = FileProxy(console, mock_file)

    print(f"Mock has isatty: {hasattr(mock_file, 'isatty')}")
    print(f"Proxy mock has isatty: {hasattr(proxy_mock, 'isatty')}")

    try:
        print(f"Proxy mock isatty value: {proxy_mock.isatty()}")
    except AttributeError as e:
        print(f"Proxy mock isatty raised: {e}")

if __name__ == "__main__":
    test_isatty_proxy()

